  director_compliance: { role: "Director, Compliance (Security)", mission: "Own security compliance — SOC2-oriented controls and continuous compliance monitoring. (Distinct from CLO legal `director_compliance`; depth note: under `managers/`; manifest authority = director.)", resp: ["Govern compliance controls (SOC2-oriented).","Run continuous compliance monitoring.","Coordinate with legal/privacy."], kpis: "Control coverage; compliance findings closed.", hitl: ["SECURITY_SEVERITY_HIGH","BRAND_LEGAL_SENSITIVE"], failure: "fail_closed", readMem: ["security:compliance:*","legal:summary"], writeMem: ["security:compliance:controls"] },
