  manager_security_operations: { role: "Manager, Security Operations", mission: "Run security operations — monitor signals and route detections to workers/IR.", resp: ["Monitor security signals (`audit.access_denied`, verdicts).","Route detections.","Escalate to IR/CSO."], kpis: "Detection routing time; false-positive rate.", hitl: ["SECURITY_SEVERITY_HIGH"], failure: "fail_closed", consumes: ["`audit.access_denied`","security verdicts","`governance.*`"], readMem: ["security:ops:*"], writeMem: ["security:ops:signals"] },
  access_control_agent: { role: "Access Control", mission: "Enforce and verify access-control decisions (RBAC × contract × token).", resp: ["Verify access requests against policy.","Flag/deny anomalous access.","Feed IAM/IR."], kpis: "Improper-access catch rate.", produces: ["`audit.access_denied` signals"], readMem: ["security:iam:*"], writeMem: ["security:fraud:signals"], failure: "fail_closed", failureNote: "`fail_closed`: deny access on any doubt." },
  financial_risk_agent: { role: "Financial Risk (Security)", mission: "Detect financial-risk/abuse signals from a security lens, complementing finance risk.", resp: ["Detect financial abuse/anomalies.","Flag to risk/fraud.","Veto unsafe financial actions."], kpis: "Financial-abuse catch rate; loss avoided.", readMem: ["security:fraud:*","finance:summary"], writeMem: ["security:fraud:signals"], failure: "fail_closed" },
  fraud_detection_agent: { role: "Fraud Detection", mission: "Flag fraudulent/anomalous activity and provide a fail-closed verdict feeding governance and the Decision Engine.", resp: ["Reason over activity signals.","Recall known fraud patterns.","Emit a fraud verdict (fail closed on doubt)."], kpis: "Fraud catch rate; false-positive rate; loss avoided.", inputs: "skylize.schemas.security.ActivitySignalIn", outputs: "skylize.schemas.security.FraudVerdictOut", deps: "BI aggregates; security patterns; the Decision Engine safety-veto.", consumes: ["`sales.signal_detected`","`audit.access_denied`"], produces: ["fraud verdicts to `sales`/`governance`"], hitl: ["SECURITY_SEVERITY_HIGH","LOW_CONFIDENCE_IRREVERSIBLE"], readMem: ["security:fraud:*","security:patterns"], writeMem: ["security:fraud:signals"], failure: "fail_closed", failureNote: "`fail_closed`: on error or doubt, block rather than pass. A reject is a safety veto outranking lower-authority approves. Matches the registry example contract." },
