  security_audit_agent: { role: "Security Audit", mission: "Continuously audit actions against the immutable audit trail for policy violations.", resp: ["Audit actions vs. policy.","Flag violations.","Feed compliance/IR."], kpis: "Violation catch rate; audit coverage.", consumes: ["`audit.*`"], produces: ["audit findings"], readMem: ["security:compliance:*","security:ops:*"], writeMem: ["security:fraud:signals"], failure: "fail_closed" },
  security_score_agent: { role: "Security Score", mission: "Risk-rank security flags deterministically (Security Score) for triage.", resp: ["Compute Security Score (severity, blast radius, confidence).","Rank flags.","Feed IR/CSO triage."], kpis: "Triage accuracy; severity calibration.", deps: "scoring models.", readMem: ["security:*"], writeMem: ["security:fraud:signals"], failure: "fail_closed", failureNote: "`fail_closed`: returns no score rather than a guess; missing score escalates rather than under-rates a threat." },
  compliance_monitor_agent: { role: "Compliance Monitor", mission: "Continuously monitor platform behavior against compliance controls and flag drift. (Stray-text file cleaned per manifest.)", resp: ["Monitor actions against compliance controls.","Flag control drift/violations.","Feed security compliance/IR."], kpis: "Drift catch rate; control coverage.", consumes: ["`audit.*`","`governance.*`"], produces: ["compliance findings"], readMem: ["security:compliance:*"], writeMem: ["security:fraud:signals"], failure: "fail_closed" },

